input.command:
python3 - <<'E'
p='bookly/app.js'
open(p,'w').write('''// S01 -> S02: day chosen -> render the slots for that day.
// Slot shape: a time string, or { time, taken: true } for a booked slot.
const slots = { "Mon 27": ["09:00", { time: "09:30", taken: true }, "10:00"], "Tue 28": [], "Wed 29": ["10:00"] };
document.querySelectorAll(".day").forEach((b) => {
  b.addEventListener("click", () => {
    document.querySelectorAll(".day").forEach((d) => d.setAttribute("aria-pressed", String(d === b)));
    renderSlots(slots[b.textContent] || []);
  });
});
function renderSlots(list) {
  const el = document.querySelector(".slots");
  el.replaceChildren();
  if (!list.length) {
    el.textContent = "Nothing free on this day. Try another.";
    return;
  }
  const grid = document.createElement("div");
  grid.className = "slot-grid";
  list.forEach((s) => {
    const { time, taken } = typeof s === "string" ? { time: s, taken: false } : s;
    const b = document.createElement("button");
    b.type = "button";
    b.className = "slot";
    b.textContent = time;
    if (taken) {
      b.disabled = true;
      b.classList.add("slot--taken");
      b.title = "Already booked";
    }
    grid.append(b);
  });
  el.append(grid);
}
''')
open('bookly/styles.css','a').write('''.day[aria-pressed="true"] { background: var(--accent); color: var(--on-accent); }
.slot-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(96px, 1fr)); gap: 8px; }
.slot { padding: 10px 0; border: 1px solid var(--accent); border-radius: var(--radius-md); background: var(--bg); color: var(--accent); font: inherit; cursor: pointer; }
.slot:hover { background: var(--accent); color: var(--on-accent); }
.slot:focus-visible, .day:focus-visible { outline: 2px solid var(--text); outline-offset: 2px; }
.slot--taken { border-color: var(--surface); background: var(--surface); color: var(--text-muted); text-decoration: line-through; cursor: not-allowed; }
.slot--taken:hover { background: var(--surface); color: var(--text-muted); }
''')
E
sed -i 's/^Public booking page with open slots,booking page,must,yes,partial,,.*/Public booking page with open slots,booking page,must,yes,yes,,S02 slot grid built from recon map/' .skillator/clone/features.csv
sed -i 's/^- \[x\] F2 .*/&\n- [x] F3 — S02 slot grid: one button per slot, taken variant, empty state. Clone of Slotly, booking page, must (clone-odo FL01, S02). Built from recon map, not from original\/booking.html./' TICKETS.md
node --check bookly/app.js && echo ok; grep -c F3 TICKETS.md

